rable\n                            ></v-text-field>\n                        </CCol>\n                    </CRow>\n                    <CRow class=\"g-0 mb-2\">\n                        <CCol md=\"12\">\n                            {{\n                                `${this.$t(\"calendar.title\")} ${this.$t(\n                                    \"color\"\n                                )}`\n                            }}\n                        </CCol>\n                        <CCol md=\"12\">\n                            <TextFieldColorPicker v-model=\"color\" />\n                        </CCol>\n                    </CRow>\n                    <CButton @click=\"submit\" color=\"primary\" class=\"px-4\">\n                        {{ $t(\"button.submit\") }}\n                        <v-progress-circular\n                            v-if=\"loading\"\n                            indeterminate\n                            color=\"primary\"\n                            :size=\"15\"\n                        ></v-progress-circular>\n                    </CButton>\n                </form>\n            </CCardBody>\n        </CCard>\n    </div>\n</template>\n\n<script>\nimport { DutyCalendar, TextFieldColorPicker } from \"@/components\";\n\nexport default {\n    name: \"CreateDuty\",\n    components: {\n        DutyCalendar,\n        TextFieldColorPicker\n    },\n    computed: {\n        datesText() {\n            if (this.dates.length === 1) {\n                return this.dates;\n            }\n            if (this.dates.length > 1) {\n                let f = new Date(this.dates[0]);\n                let t = new Date(this.dates[1]);\n                if (f.toDateString() === t.toDateString()) {\n                    return this.dates[0];\n                }\n                let sorted = this.dates.sort(\n                    (a, b) => new Date(a) - new Date(b)\n                );\n                this.dates = sorted;\n                return sorted.join(\" － \");\n            }\n        }\n    },\n    data() {\n        return {\n            loading: false,\n            user: \"\",\n            dates: [],\n            start: \"\",\n            end: \"\",\n            color: \"#0D47A1FF\",\n            errors: {},\n            dateMenu: false,\n            autocomplete: {\n                user: {\n                    items: [],\n                    loading: false\n                }\n            }\n        };\n    },\n    watch: {\n        \"autocomplete.user.search\": function(val) {\n            let self = this;\n            let cli = self.autocomplete.user;\n            if (cli.items.length > 0 || cli.loading) {\n                return;\n            }\n            self.autocomplete.user.loading = true;\n            let data = {\n                user_id: self.userId,\n                role: \"EMPLOYEE\"\n            };\n            this.$store\n                .dispatch(\"user/get\", data)\n                .then(response => {\n                    let data = response.data;\n                    self.autocomplete.user.items = response.data;\n                    self.autocomplete.user.loading = false;\n                    if (self.$route.params.userId) {\n                        let id = self.$route.params.userId;\n                        for (const item of data) {\n                            if (`${item.id}` === `${id}`) {\n                                self.user = item;\n                                // console.log(item);\n                                break;\n                            }\n                        }\n                    }\n                })\n                .catch(error => {\n                    self.autocomplete.user.loading = false;\n                });\n        }\n    },\n    methods: {\n        submit() {\n            let self = this;\n            if (self.loading) {\n                return;\n            }\n            self.loading = true;\n            let data = {\n                user: self.user,\n                dates: self.dates,\n                start: self.start,\n                end: self.end,\n                color: self.color\n            };\n            this.$store\n                .dispatch(\"user/duty/create\", data)\n                .then(response => {\n                    self.loading = false;\n                    self.errors = {};\n                    self.$router.back();\n                })\n                .catch(error => {\n                    self.errors = error.response.data?.data;\n                    self.loading = false;\n                });\n        }\n    }\n};\n</script>\n\n<style scoped>\n.v-text-field :deep(input) {\n    font-size: 0.8em;\n    font-weight: 100;\n}\n.v-text-field :deep(label) {\n    font-size: 0.8em;\n}\n.v-text-field :deep(button) {\n    font-size: 0.8em;\n}\n</style>\n"],"sourceRoot":""}]);
